package com.gym.management;
import com.gym.management.dto.PaymentRequest;import com.gym.management.entity.*;import com.gym.management.exception.*;import com.gym.management.payment.MockPaymentGateway;import com.gym.management.repository.*;import com.gym.management.service.*;
import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.LocalDate;import java.util.Optional;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class PaymentServiceTests {
 private PaymentService service(PaymentRepository repo,PaymentStatusEventRepository events,GymService gym){return new PaymentService(repo,events,gym,new MockPaymentGateway());}
 @Test void approvedMembershipPaymentActivatesMembershipAndCannotBeProcessedTwice(){PaymentRepository repo=mock(PaymentRepository.class);PaymentStatusEventRepository events=mock(PaymentStatusEventRepository.class);GymService gym=mock(GymService.class);Member member=new Member();Plan plan=new Plan("Monthly",30,new BigDecimal("50.00"),"Access");when(gym.member(1L)).thenReturn(member);when(gym.plan(2L)).thenReturn(plan);when(repo.save(any())).thenAnswer(i->i.getArgument(0));PaymentService svc=service(repo,events,gym);
  Payment p=svc.create(new PaymentRequest(1L,2L,PaymentMethod.CARD,PaymentPurpose.MEMBERSHIP_PURCHASE,"key-1",new BigDecimal("999.00")));assertEquals(new BigDecimal("50.00"),p.getAmount());when(repo.lockById(p.getId())).thenReturn(Optional.of(p));assertEquals(PaymentStatus.SUCCESS,svc.process(p.getId(),true).getStatus());assertNotNull(member.getMembershipEnd());assertEquals(LocalDate.now().plusDays(30),member.getMembershipEnd());assertThrows(ConflictException.class,()->svc.process(p.getId(),false));}
 @Test void declinedRequestStaysFailedAndHasNoMembershipEffect(){PaymentRepository repo=mock(PaymentRepository.class);PaymentStatusEventRepository events=mock(PaymentStatusEventRepository.class);GymService gym=mock(GymService.class);Member member=new Member();when(gym.member(1L)).thenReturn(member);when(gym.plan(2L)).thenReturn(new Plan("Monthly",30,new BigDecimal("50"),null));when(repo.save(any())).thenAnswer(i->i.getArgument(0));PaymentService svc=service(repo,events,gym);Payment p=svc.create(new PaymentRequest(1L,2L,PaymentMethod.UPI,PaymentPurpose.MEMBERSHIP_PURCHASE,"key-2",null));when(repo.lockById(p.getId())).thenReturn(Optional.of(p));Payment failed=svc.process(p.getId(),false);assertEquals(PaymentStatus.FAILED,failed.getStatus());assertNotNull(failed.getFailureReason());assertNull(member.getMembershipEnd());}
 @Test void idempotentCreateReturnsExistingAndRejectsKeyReuse(){PaymentRepository repo=mock(PaymentRepository.class);PaymentStatusEventRepository events=mock(PaymentStatusEventRepository.class);GymService gym=mock(GymService.class);Member m=mock(Member.class);when(m.getId()).thenReturn(1L);Payment prior=new Payment("TXN-A","key",m,null,new BigDecimal("1"),PaymentMethod.CASH,PaymentPurpose.OUTSTANDING_FEE);when(repo.findByIdempotencyKey("key")).thenReturn(Optional.of(prior));PaymentService svc=service(repo,events,gym);assertSame(prior,svc.create(new PaymentRequest(1L,null,PaymentMethod.CASH,PaymentPurpose.OUTSTANDING_FEE,"key",BigDecimal.ONE)));assertThrows(ConflictException.class,()->svc.create(new PaymentRequest(2L,null,PaymentMethod.CASH,PaymentPurpose.OUTSTANDING_FEE,"key",BigDecimal.ONE)));assertThrows(ConflictException.class,()->svc.create(new PaymentRequest(1L,null,PaymentMethod.UPI,PaymentPurpose.OUTSTANDING_FEE,"key",BigDecimal.ONE)));assertThrows(ConflictException.class,()->svc.create(new PaymentRequest(1L,null,PaymentMethod.CASH,PaymentPurpose.OUTSTANDING_FEE,"key",new BigDecimal("2.00"))));}
 @Test void rejectsInvalidOutstandingAmount(){GymService gym=mock(GymService.class);Member m=new Member();when(gym.member(1L)).thenReturn(m);PaymentService svc=service(mock(PaymentRepository.class),mock(PaymentStatusEventRepository.class),gym);assertThrows(IllegalArgumentException.class,()->svc.create(new PaymentRequest(1L,null,PaymentMethod.CASH,PaymentPurpose.OUTSTANDING_FEE,"bad",BigDecimal.ONE.negate())));}
 @Test void collectionsUseSuccessfulOnlyDatabaseAggregate(){PaymentRepository repo=mock(PaymentRepository.class);when(repo.successfulTotal()).thenReturn(new BigDecimal("100.00"));PaymentService svc=service(repo,mock(PaymentStatusEventRepository.class),mock(GymService.class));assertEquals(new BigDecimal("100.00"),svc.revenue());verify(repo).successfulTotal();}
}
